function atomLine(def: RefAtom, base: StandardBases, seqId: number, serialNo: number) {
    const template = new Array<string>(80);
    template.fill(' ');

    const put = (s: string, start: number) => {
        putStr(template, s, start);
    };

    put('ATOM', 0);
    put(serialNo.toString().padStart(5), 6);
    put(def[0], 12 + (def[0].length < 4 ? 1 : 0));
    put(base.padStart(3), 17);
    put('A', 21);
    put(seqId.toString().padStart(3), 22);
    put(def[1].toString().padStart(8), 30);
    put(def[2].toString().padStart(8), 38);
    put(def[3].toString().padStart(8), 46);
    put('1.00'.padStart(6), 54);
    put('1.00'.padStart(6), 60);
    put(def[0][0].padStart(2), 76);

    return template.join('');
}

function isHydrogen(refAtom: RefAtom) {
    return refAtom[0][0] === 'H';
}

function putStr(target: string[], s: string, start: number) {
    if (s.length + start > target.length)
        throw new Error('Cannot put string into string');

    for (let idx = 0; idx < s.length; idx++)
        target[idx + start] = s[idx];
}

export function referencePdb(ntc: NtCs, firstBase: KnownBase, secondBase: KnownBase, showHydrogens: boolean) {
    const stdFirstBase = KnownBasesProps[firstBase][2];
    const stdSecondBase = KnownBasesProps[secondBase][2];
    const firstIsDNA = KnownBasesProps[firstBase][1];
    const secondIsDNA = KnownBasesProps[secondBase][1];

    let pdb = '';

    let serialNo = 0;
    for (const refAtom of ReferenceDinuleotides[ntc].primary[0]) {
        if ((refAtom[0] === "O2'" && firstIsDNA) || (isHydrogen(refAtom) && !showHydrogens))
            continue;
        pdb += atomLine(refAtom, stdFirstBase, 1, serialNo++) + '\n';
    }
    for (const refAtom of ReferenceDinuleotides[ntc][stdFirstBase][0]) {
        if (isHydrogen(refAtom) && !showHydrogens)
            continue;
        pdb += atomLine(refAtom, stdFirstBase, 1, serialNo++) + '\n';
    }

    for (const refAtom of ReferenceDinuleotides[ntc].primary[1]) {
        if ((refAtom[0] === "O2'" && secondIsDNA) || (isHydrogen(refAtom) && !showHydrogens))
            continue;
        pdb += atomLine(refAtom, stdSecondBase, 2, serialNo++) + '\n';
    }
    for (const refAtom of ReferenceDinuleotides[ntc][stdSecondBase][1]) {
        if (isHydrogen(refAtom) && !showHydrogens)
            continue;
        pdb += atomLine(refAtom, stdSecondBase, 2, serialNo++) + '\n';
    }

    pdb += 'TER\nEND\n';

    return pdb;
}
